def transform(grid):
    # Each row-block depicts a 3x6 binary stencil. The upper 5 pattern is
    # transformed by the 2 pattern, with 4-pattern cells specifying erase.
    out = [row[:] for row in grid[:3]]
    for r in range(3):
        for c in range(6):
            if out[r][c] == 0:
                if grid[r+6][c] == 2 and grid[r+3][c] != 4:
                    out[r][c] = 2
                elif grid[r+3][c] == 4:
                    out[r][c] = 4
    return out
